CREATE OR REPLACE FUNCTION public.icash_prepare_seller_contacts(p_account uuid, p_lead uuid, p_screening uuid, p_deal uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare l public.icash_seller_intakes;e jsonb;r public.icash_operation_rates;chosen_sender text;price bigint;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
 if not found then return;end if;
 perform 1 from public.icash_deal_files where id=p_deal and account_id=p_account and screening_id=p_screening and stage='draft' and coalesce(terms->>'practice','false')<>'true' for share;
 if not found then return;end if;
 select * into l from public.icash_seller_intakes where id=p_lead;
 e:=public.icash_seller_contact_evidence(p_account,p_screening,p_lead,l.phone);
 if e is null then return;end if;
 if exists(select 1 from public.icash_property_controls pc join public.icash_screening_jobs s on s.account_id=pc.account_id and s.snapshot->>'propertyId'=pc.property_id where s.id=p_screening and s.account_id=p_account and pc.manual)
  or exists(select 1 from public.icash_handoffs where account_id=p_account and screening_id=p_screening and state<>'resolved') then return;end if;
 if public.icash_outreach_voice_current(p_account) then
  insert into public.icash_contact_permissions(account_id,screening_id,party,phone,contact_key,timezone,local_start_hour,local_end_hour,permission_evidence,permission_until,dnc_checked_at,dnc_clear,seller_intake_id)
  values(p_account,p_screening,'seller',l.phone,encode(sha256(convert_to(l.phone,'UTF8')),'hex'),e->>'timezone',9,20,e->>'evidence',(e->>'until')::timestamptz,null,false,l.id)
  on conflict(account_id,screening_id,party,contact_key) do nothing;
 end if;
 if not public.icash_outreach_sms_current(p_account) then return;end if;
 -- Ambiguous sender configuration must not silently select a different business number.
 chosen_sender:=public.icash_property_text_sender(p_account,p_deal,l.phone);if chosen_sender is null then return;end if;
 select * into r from public.icash_operation_rates where operation='sms_send' and public.icash_sms_intake_rate_current(id) order by verified_at desc,charge_cents,id limit 1 for share;
 if not found then return;end if;
 select customer_micros into price from public.icash_communication_prices where operation='sms_segment' for share;
 perform public.icash_retire_expired_practice_threads(p_account,chosen_sender,l.phone);
 insert into public.icash_text_threads(sender_pool_assigned,account_id,deal_id,sender,recipient,permission_until,permission_evidence,timezone,dnc_checked_at,dnc_clear,sms_rate_id,paused,ai_mode,party,seller_intake_id,seller_sms_rate_hash,seller_sms_price_micros)
 values(true,p_account,p_deal,chosen_sender,l.phone,(e->>'until')::timestamptz,e->>'evidence',e->>'timezone',null,false,r.id,false,'auto','seller',l.id,encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex'),price)
 on conflict(account_id,deal_id,sender,recipient) where retired_at is null and owner_buyer_test_id is null do nothing;
 -- Never reassign, unpause, renew or overwrite an existing contact on a retry.
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_seller_text_event(p_event text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_text_messages;job uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into m from public.icash_text_messages where event_id=p_event and direction='incoming' and state='received';
 if found and public.icash_seller_sms_call_current(m.account_id,m.id) then
  job:=public.icash_queue_seller_sms_call(m.account_id,m.id);
  update public.icash_voice_jobs set state='issued',updated_at=now() where id=job and account_id=m.account_id and state='ready' and due_at<=now();
  return case when job is not null then jsonb_build_object('accountId',m.account_id,'voiceJobId',job) else null end;
 end if;
 return public.icash_prepare_seller_text_event_before_call_now(p_event);
end $function$

CREATE OR REPLACE FUNCTION public.icash_resolve_recent_owner_reply(p_account uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_text_messages;q public.icash_sms_route_reviews;r public.icash_sms_routes;context jsonb;t public.icash_text_threads;outgoing uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into m from public.icash_text_messages where id=p_message and account_id=p_account;
 select * into q from public.icash_sms_route_reviews where message_id=m.id and account_id=p_account;
 if m.id is null or m.thread_id is not null or m.state<>'needs_review' or m.direction<>'incoming' or m.created_at<now()-interval '15 minutes' or q.resolved_at is not null then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(q.recipient,74));
 select * into r from public.icash_sms_routes where sender=q.sender and recipient=q.recipient and account_id=p_account for update;
 if r.revision is distinct from m.route_revision then return null;end if;
 context:=public.icash_sms_recent_owner_question(q.sender,q.recipient,m.created_at);
 if context is null or context->>'accountId'<>p_account::text then return null;end if;
 select * into t from public.icash_text_threads where id=(context->>'threadId')::uuid and account_id=p_account;
 insert into public.icash_sms_owner_reply_resolutions(source_id,question_id,account_id,thread_id,route_revision)
 values(m.id,(context->>'questionId')::uuid,p_account,t.id,r.revision) on conflict do nothing;
 if not public.icash_sms_owner_reply_resolution_current(m.id,p_account,t.id,r.revision) then return null;end if;
 update public.icash_sms_routes set needs_review=false where sender=r.sender and recipient=r.recipient;
 update public.icash_text_messages set thread_id=t.id,state='received',updated_at=now() where id=m.id;
 update public.icash_sms_route_reviews set resolved_at=now(),resolution_revision=r.revision,
 reason='Bound to the delivered ownership question; no offer or contract authority inferred.' where message_id=m.id;
 -- Continue through the existing consent/financial/credit-aware response engine.
 outgoing:=public.icash_prepare_sms_inbound_reply(p_account,t.id,m.id);
 return jsonb_build_object('threadId',t.id,'messageId',outgoing);
end $function$

CREATE OR REPLACE FUNCTION public.icash_sms_message_route()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;r public.icash_sms_routes;v jsonb;pair_sender text;pair_recipient text;
begin
 if TG_OP='UPDATE' then
  if row(new.thread_id,new.account_id,new.direction,new.route_revision) is distinct from row(old.thread_id,old.account_id,old.direction,old.route_revision) then
   if not (old.thread_id is null and new.thread_id is not null and old.state='needs_review' and new.state='received'
    and row(new.account_id,new.direction,new.route_revision,new.body,new.created_at,new.event_id,new.provider_id,new.attachments)
      is not distinct from row(old.account_id,old.direction,old.route_revision,old.body,old.created_at,old.event_id,old.provider_id,old.attachments)
    and public.icash_sms_owner_reply_resolution_current(old.id,new.account_id,new.thread_id,new.route_revision))
   then raise exception 'SMS message route is immutable';end if;
  end if;
  return new;
 end if;
 -- Provider retries and repeated queue requests must not advance routing state.
 if exists(select 1 from public.icash_text_messages m where (new.event_id is not null and m.event_id=new.event_id) or (new.provider_id is not null and m.provider_id=new.provider_id) or (new.request_key is not null and m.request_key=new.request_key)) then return null;end if;
 if new.thread_id is not null then
 select * into t from public.icash_text_threads where id=new.thread_id and account_id=new.account_id;
 if not found then raise exception 'SMS message account mismatch';end if;
 pair_sender:=t.sender;pair_recipient:=t.recipient;
 elsif new.direction='incoming' then
 select payload->'data' into v from public.icash_text_events where id=new.event_id;
 pair_sender:=v->>'to';pair_recipient:=v->>'from';
 end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform pg_advisory_xact_lock(hashtextextended(pair_recipient,74));
 select * into r from public.icash_sms_routes where sender=pair_sender and recipient=pair_recipient for update;
 if new.direction='outgoing' then
  if r.account_id is distinct from new.account_id or (r.needs_review and not public.icash_seller_clarification_current(new.account_id,new.thread_id,new.request_key,new.body,r.revision) and not (cardinality(new.asset_ids)=0 and new.attachments='[]'::jsonb and public.icash_fresh_intake_opener_current(new.account_id,new.thread_id,new.request_key,new.body,r.revision))) or t.retired_at is not null then raise exception 'SMS property routing requires review';end if;
 elsif r.account_id is not null then
  -- Any incoming message invalidates queued decisions; ambiguous replies hold all
  -- properties on the pair until an explicit property reply or human review.
  update public.icash_sms_routes set revision=revision+1,needs_review=(new.thread_id is null) where sender=pair_sender and recipient=pair_recipient returning * into r;
  if new.thread_id is null then new.account_id:=r.account_id;new.state:='needs_review';end if;
 end if;
 new.route_revision:=r.revision;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_sms_resolve_property(p_sender text, p_recipient text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare x public.icash_owner_buyer_tests;last_test timestamptz;chosen uuid;
begin
 select * into x from public.icash_owner_buyer_tests where sender=p_sender and phone=p_recipient order by created_at desc limit 1;
 if found then
  select max(created_at) into last_test from public.icash_text_messages where thread_id=x.thread_id and direction='outgoing'
   and state in ('accepted','delivered') and provider_id is not null;
  if last_test is not null and public.icash_sms_thread_review_current(x.account_id,x.thread_id,false) then return x.thread_id;end if;
  -- After expiry, a reply to the test must not silently become a seller reply.
  -- A later real seller message or an explicit matching street reestablishes it.
  if last_test is not null and not exists(select 1 from public.icash_non_test_text_threads t join public.icash_text_messages m on m.thread_id=t.id
   where t.sender=p_sender and t.recipient=p_recipient and m.direction='outgoing' and m.state in ('accepted','delivered') and m.provider_id is not null and m.created_at>last_test) then
   select t.id into chosen from public.icash_non_test_text_threads t join public.icash_deal_files d on d.id=t.deal_id and d.account_id=t.account_id
   where t.sender=p_sender and t.recipient=p_recipient and t.retired_at is null
   and position(' '||public.icash_sms_normalize_address(split_part(d.terms->>'address',',',1))||' ' in ' '||public.icash_sms_normalize_address(p_body)||' ')>0;
   return chosen;
  end if;
 end if;
 return public.icash_sms_resolve_before_owner_buyer_test(p_sender,p_recipient,p_body);
end $function$

CREATE OR REPLACE FUNCTION public.icash_submit_bot_demo_intake(p_actor uuid, p_account uuid, p_request uuid, p_guest text, p_name text, p_address text, p_phone text, p_consented boolean, p_duplicate text, p_timezone text, p_agent_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prior public.icash_seller_intakes;canonical uuid;new_id uuid;attribution jsonb;
 consent_version constant text:='icash-x-demo-contact-2026-10-10.1';
 consent_text constant text:='I agree to calls and texts from iCash X about this property demo, including automated texts and AI-generated voice calls. I have permission to use this number. Consent is not a condition of purchase. Message/data rates may apply. Reply STOP to end texts.';
 sharing_text constant text:='iCash X uses the details you enter to research the property and demonstrate the bot in the presenting account’s workspace. Demo requests are not distributed to other customer accounts. No offer or sale is guaranteed.';
begin
 perform 1 from public.icash_accounts where id=p_account and owner_user_id=p_actor for share;
 if not found then raise exception 'Presenting account required';end if;
 if p_consented is distinct from true or p_guest is null or p_guest!~'^[a-f0-9]{64}$'
  or p_agent_hash is null or p_agent_hash!~'^[a-f0-9]{64}$' or p_duplicate is null or p_duplicate!~'^[a-f0-9]{64}$'
  or not exists(select 1 from public.icash_timezone_names where name=p_timezone) then raise exception 'Valid demo consent required';end if;
 attribution:=jsonb_build_object('source','icash_x_demo','demoAccountId',p_account,'contactTimezone',p_timezone,'contactTimezoneSource','seller_browser','measurementOptOut',true);
 perform pg_advisory_xact_lock(hashtextextended(p_duplicate,0));
 select * into prior from public.icash_seller_intakes where request_id=p_request;
 if found then
  if row(prior.guest_hash,prior.name,prior.address,prior.phone,prior.ai_consented,prior.consent_version,prior.consent_text,prior.sharing_text,prior.attribution)
   is distinct from row(p_guest,p_name,p_address,p_phone,p_consented,consent_version,consent_text,sharing_text,attribution) then raise exception 'Submission retry mismatch';end if;
  return prior.id;
 end if;
 select id into canonical from public.icash_seller_intakes where duplicate_key=p_duplicate and state<>'duplicate'
  and public.icash_demo_intake_current(icash_seller_intakes.id,p_account)
  and created_at>now()-interval '90 days' order by created_at limit 1;
 insert into public.icash_seller_intakes(request_id,guest_hash,name,address,phone,duplicate_key,ai_consented,consent_version,consent_text,sharing_text,attribution,agent_hash,state,canonical_id,owner_claimed,email_consented,contact_consent_scope)
 values(p_request,p_guest,p_name,p_address,p_phone,p_duplicate,true,consent_version,consent_text,sharing_text,attribution,p_agent_hash,case when canonical is null then 'received' else 'duplicate' end,canonical,false,false,'icash_x_demo')
 returning id into new_id;
 -- Demo requests are deliberately excluded from seller ad conversion events.
 return new_id;
end $function$
